import{z as o,x as l,o as e,c as s,q as B,j as r,D as a,d as n,s as t,S as i}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"证据的分级与综合","description":"","frontmatter":{"title":"证据的分级与综合","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ca-evidence-hierarchy.md","filePath":"econ/ca-evidence-hierarchy.md","lastUpdated":1791413859000}'),d={name:"econ/ca-evidence-hierarchy.md"};function c(C,E,D,p,h,_){const A=l("Mermaid");return e(),s("div",null,[E[2]||(E[2]=B('<h1 id="证据的分级与综合" tabindex="-1">证据的分级与综合 <a class="header-anchor" href="#证据的分级与综合" aria-label="Permalink to &quot;证据的分级与综合&quot;">​</a></h1><div class="epigraph"><p>证据分级分级的不是方法的名号，而是威胁被处理掉的顺序；金字塔的每一层其实是一张威胁清单。</p><footer>—— 据 Guyatt 等, GRADE 系列, BMJ 2008；Cochrane Collaboration 整理</footer></div><p><a href="/econ/ca-env-policy-evidence">上一课</a>在环境政策里见识了证据最缺、威胁最多的应用域。四个领域走完，决策者手里是一摞相互冲突的估计：小班、上调、扩保、限排，每个题目下都有几十个读数。缺口从「怎么估」移到「信哪个」：把 RCT 永远排在观察研究之上这种金字塔口诀，既救不了糟糕的实验，也冤枉了干净的自然实验。本课把分级与综合写成程序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单一研究只是证据的原材料。同一政策下的读数散落四周：设计不同、人群不同、时点不同、发表与否不同。直接拿最近一篇或最显著的一篇下结论，会同时吃到三种偏倚：设计偏倚（识别契约有洞）、异质性（效应随人群与场景移动）、发表选择（显著为负或显著为正的估计更容易见刊——<a href="/econ/minimum-wage-debates">最低工资的元分析</a>已经演示过漏斗图左尾）。缺口是两道工序：给单研究<strong>评级</strong>，把同题研究<strong>合成</strong>——且两道工序都要能审计。</p><p><span class="marginnote">发表偏倚就是「显著的更容易见刊」：十个效应为零的研究各自测不出东西，一个碰巧显著的上刊，读者只看见那一个。漏斗图把各研究的估计值按精度排开，没有偏倚时应呈对称漏斗；缺了一角，就说明有一批研究被藏在了抽屉里。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分级用 GRADE 的骨架：起点按设计给档（RCT 高、观察研究低），然后用固定的降档域修正——偏倚风险、不一致性、间接性、不精确性、发表偏倚——干净的<a href="/econ/pe-rdd-deep">断点回归</a>可以站回高档，有流失的 RCT 必须降档；大效应与剂量反应允许观察证据升档。合成按 <a href="/econ/pe-meta-analysis">Meta 分析</a>的口径：注册与协议先行，避免只合成看得见的研究；随机效应模型吸收研究间方差；漏斗图不对称性用 Egger 类检验读发表选择。工程侧配三件套：预注册与结果登记（把分析计划钉在见到数据之前）、<a href="/econ/multiple-testing-econ">多重检验</a>校正（结果表一长，假阳性自动涌现）、<a href="/econ/clustered-se">聚类标准误</a>对准抽样层级。</p>',8)),(e(),r(i,null,{default:a(()=>[t(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E5%8D%95%E7%A0%94%E7%A9%B6%EF%BC%9A%E4%BC%B0%E8%AE%A1%E4%B8%8E%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20GRA%5B%22%E8%AF%84%E7%BA%A7%EF%BC%9A%E9%99%8D%E6%A1%A3%E5%9F%9F%E9%80%90%E9%A1%B9%E8%BF%87%22%5D%0A%20%20GRA%20--%3E%20REG%5B%22%E6%B3%A8%E5%86%8C%E4%B8%8E%E5%8D%8F%E8%AE%AE%EF%BC%9A%E9%98%B2%E4%BA%8B%E5%90%8E%E6%94%B9%E9%A2%98%22%5D%0A%20%20REG%20--%3E%20MET%5B%22%E5%90%88%E6%88%90%EF%BC%9A%E9%9A%8F%E6%9C%BA%E6%95%88%E5%BA%94%E4%B8%8E%E5%BC%82%E8%B4%A8%E6%80%A7%22%5D%0A%20%20MET%20--%3E%20FUN%5B%22%E5%8F%91%E8%A1%A8%E5%81%8F%E5%80%9A%EF%BC%9A%E6%BC%8F%E6%96%97%E5%9B%BE%E4%B8%8E%E6%A0%A1%E6%AD%A3%22%5D%0A%20%20FUN%20--%3E%20DEC%5B%22%E5%86%B3%E7%AD%96%EF%BC%9A%E6%8C%89%20welfare%20%E6%B3%9B%E5%87%BD%E6%9D%83%E9%87%8D%22%5D%0A%20%20MET%20--%3E%7C%E5%BC%82%E8%B4%A8%E6%80%A7%E5%A4%A7%7C%20SUB%5B%22%E6%8C%89%E4%BA%BA%E7%BE%A4%E5%88%86%E4%BA%9A%E7%BB%84%E7%9A%84%E5%85%83%E5%9B%9E%E5%BD%92%22%5D%0A%20%20SUB%20--%3E%20DEC%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<p><span class="marginnote">Cochrane 的徽标是一道旧伤口：1987 年把早产风险孕妇使用糖皮质激素的七个 RCT 合成，单独看都不显著，合成却读出新生儿死亡的显著下降——疗法已可用十余年，只欠一次综合。单研究的「不显著」不是「无效」，这是分级与综合的第一课。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分级为什么必须按威胁清单而不是按方法名号：一种设计的价值等于它挡住了哪些威胁——随机化挡选择与混淆，断点挡阈值附近的其余差异，<a href="/econ/iv-weak-instruments">工具变量</a>挡内生但引入单调性与排除性，<a href="/econ/difference-in-differences">双重差分</a>挡共同冲击但赌平行趋势。评级就是逐项核对挡了没有、挡得干不干净，所以同一个方法在不同应用里评级不同。合成的机制则把矛盾变成信息：点估计的离散若超出抽样误差，随机效应把它记为真实的异质性，<a href="/econ/pe-meta-analysis">元回归</a>再去找调节变量——设计强度、人群、剂量就是候选调节项。综合的产出不是一个大平均，而是「效应多大、在谁身上、证据还缺哪块」的分布。不这么做会错在哪：把异质性研究硬合成一个点，会同时掩盖赢家与输家；把「证据不足」读成「证据为零」，会把本该等数据的政策推成武断行动。</p>',3)),(e(),r(i,null,{default:a(()=>[t(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20RCT%5B%22%E9%9A%8F%E6%9C%BA%E5%8C%96%22%5D%20--%3E%20B1%5B%22%E6%8C%A1%3A%20%E9%80%89%E6%8B%A9%E4%B8%8E%E6%B7%B7%E6%B7%86%22%5D%0A%20%20RDD%5B%22%E6%96%AD%E7%82%B9%E5%9B%9E%E5%BD%92%22%5D%20--%3E%20B2%5B%22%E6%8C%A1%3A%20%E9%98%88%E5%80%BC%E9%99%84%E8%BF%91%E7%9A%84%E5%85%B6%E4%BD%99%E5%B7%AE%E5%BC%82%22%5D%0A%20%20IV%5B%22%E5%B7%A5%E5%85%B7%E5%8F%98%E9%87%8F%22%5D%20--%3E%20B3%5B%22%E6%8C%A1%3A%20%E5%86%85%E7%94%9F%2C%20%E4%BD%86%E8%87%AA%E5%B8%A6%E5%8D%95%E8%B0%83%E6%80%A7%E4%B8%8E%E6%8E%92%E9%99%A4%E6%80%A7%E8%A6%81%E6%B1%82%22%5D%0A%20%20DID%5B%22%E5%8F%8C%E9%87%8D%E5%B7%AE%E5%88%86%22%5D%20--%3E%20B4%5B%22%E6%8C%A1%3A%20%E5%85%B1%E5%90%8C%E5%86%B2%E5%87%BB%2C%20%E4%BD%86%E8%B5%8C%E5%B9%B3%E8%A1%8C%E8%B6%8B%E5%8A%BF%22%5D%0A%20%20B1%20--%3E%20G%5B%22%E8%AF%84%E7%BA%A7%3A%20%E9%80%90%E9%A1%B9%E6%A0%B8%E5%AF%B9%E6%8C%A1%E4%BA%86%E6%B2%A1%E6%9C%89%22%5D%0A%20%20B2%20--%3E%20G%0A%20%20B3%20--%3E%20G%0A%20%20B4%20--%3E%20G%0A%20%20G%20--%3E%20OUT%5B%22%E5%90%8C%E4%B8%80%E6%96%B9%E6%B3%95%2C%20%E5%BA%94%E7%94%A8%E4%B8%8D%E5%90%8C%2C%20%E6%A1%A3%E4%BD%8D%E4%B8%8D%E5%90%8C%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">GRADE 可以想成体检扣分制：RCT 起点分高，但流失严重、结局换了代理、区间太宽，照样逐项扣分；观察研究起点分低，可若效应巨大且呈剂量反应，也能加分站回高档。方法的名号不加分，漏洞才扣分——这正是「分级分的不是名号」的读法。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>评级再高也不直接等于决策：把证据换算成行动要过<a href="/econ/pe-decision-target">以决策为目标</a>的泛函——错误的代价不对称时，「证据尚不充分」与「立即行动」之间的阈值由决策问题定，不由证据等级定；试点值多少钱，由<a href="/econ/pe-decision-target">信息价值</a>的算术给出。GRADE 也不解决证据语料本身的结构性缺口：从未被研究的人群与从未被试的剂量，在金字塔的每一层都缺席，只能靠外推与<a href="/econ/se-validation">结构模型的验证</a>补位。本课的边界因此是：分级与综合处理已有证据的秩序，不生产缺失的证据。</p><p><span class="marginnote">初学者容易把「证据不足」读成「没有效应」。糖皮质激素的七个 RCT 单独看都不显著、合成后显著，就是反例——单研究的「测不出」常常只是样本太小。正确动作是再收数据或等新证据，而不是宣布无效，也不是抢着武断行动。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分级的对象是威胁清单，不是方法名号；同一设计在不同应用里评级不同。</li><li>合成先行于阅读：注册、协议、随机效应、漏斗图校正，缺一道工序就引进一种偏倚。</li><li>异质性是信息不是噪声：元回归找调节变量，硬合成会掩盖赢家与输家。</li><li>证据等级不替代决策泛函：阈值由错误代价的对称性定，缺口靠外推与结构补位。</li><li>出处：Guyatt 等, GRADE 系列, BMJ 2008；DerSimonian and Laird, Controlled Clinical Trials 1986；Egger 等, BMJ 1997；Card, Kluve and Weber, JEP 2018。</li></ul>',6))])}const T=o(d,[["render",c]]);export{m as __pageData,T as default};
